ROOT=Path(__file__).resolve().parent
def load(n):return json.loads((ROOT/n).read_text(encoding='utf8'))
def digest(b):return hashlib.sha256(b).hexdigest()

def primary():
    out=[]
    for r in load('phase40-primary-manifest.json'):
        before=ROOT/'ghidra'/r['before'];after=ROOT/'ghidra'/r['after'];memory=ROOT/'ghidra'/r['memory'];assert before.read_text().rstrip()==after.read_text().rstrip()
        m=json.loads(memory.read_text());b=bytes(m['data']);assert int(m['address'],16)==r['address'] and len(b)==m['length']==r['length'] and b==pe_read(Path(r['exe']).read_bytes(),r['address'],r['length'])
        out.append({**r,'before_sha256':digest(before.read_bytes()),'memory_sha256':digest(memory.read_bytes()),'program_bytes_sha256':digest(b)})
    return out

def native_data():
    b=(DATA.parent.parent/'DKII-DX.exe').read_bytes();angle_tables=[]
    for j,ix,permitted in [(0x449EE8,0x449F08,0x449E13),(0x449F1C,0x449F3C,0x449EB9)]:
        raw=pe_read(b,j,32);indices=pe_read(b,ix,18);table=struct.unpack('<8I',raw);modes=[i+1 for i,x in enumerate(indices) if table[x]==permitted];assert modes==[1,2,10,11]
        angle_tables.append(dict(jump_table=hex(j),jump_hex=raw.hex(),indices=hex(ix),index_hex=indices.hex(),unclamped_modes=modes,unclamped_target=hex(permitted)))
    writer=(ROOT/'ghidra/phase30-things-writer-before.txt').read_text();tags=sorted({int(x,16) for x in re.findall(r'MOV dword ptr \[ESP \+ 0x(?:14|18|1c)\],0x(c[2-d])\s',writer)})
    assert tags==list(range(194,205)) and '0xcd' not in writer.lower()
    return dict(angle_tables=angle_tables,writer_tag_assignments=tags,writer_contains_CD=False,writer_evidence_file='phase30-things-writer-before.txt')

def corpus():
    files=[];total=0
    for row in load('placed-room-semantics.json')['corpus']['files']:
        p=Path(row['file']);b=p.read_bytes();assert digest(b)==row['sha256'];count=sum(1 for s in fmt.parse(b) if s.signature==190 for r in s.records if fmt.u32(r)==205);total+=count;files.append(dict(file=str(p),sha256=row['sha256'],cameras=count))
    return dict(thing_files=len(files),camera_records=total,files=files,scope='109 corpus map Things files plus standalone AutoSaveThings. No CD record present; synthetic fixtures do not imply shipped use.')

