    for off,name in [(36,'ViewDistance'),(48,'Zoom'),(60,'Lens')]:fields.append(dict(offset=off,bytes=12,name=name,storage='3 DWORD bit patterns: value,min,max',scope='No division/rescaling in converter/preset storage. Active setters use signed32 exclusive upper bound; display units are not independently measured.'))
    fields.extend([dict(offset=72,bytes=4,name='Flags',storage='DWORD',scope='OR into intermediate8C. Active flags control specific operations; preserve upper/unrecognized bits.'),dict(offset=76,bytes=6,name='Angles',storage='3 WORDs',scope='Yaw/Roll/Pitch baseline order. Active relative angle helper wraps permitted values to11 bits; mode-dependent limits for roll/pitch.'),dict(offset=82,bytes=1,name='Id',storage='BYTE',scope='Both converters read only this byte. Native preset load accepts1..18;0 and19..255 ignored after checksum.'),dict(offset=83,bytes=1,name='OpaqueTail',storage='BYTE',scope='Baseline treated this as upper byte of WORD Id. Neither converter copies it; intermediate97 remains prior seed. Preserve raw byte.')])
    flags=[dict(mask=m,name=n,evidence=e,scope=s) for m,n,e,s in [
        (1,'DisableRelativeYaw','449D40:449D57','Skips relative update to activeWORDD84; absolute angle setter449D00 is a different path.'),(2,'DisableRelativeRoll','449D40:449D7B','Skips relative roll at activeWORDD88; otherwise mode-dependent constraints.'),(4,'DisableRelativePitch','449D40:449E32','Skips relative pitch at activeWORDD86; otherwise mode-dependent constraints.'),
        (8,'DisableRelativeZoom','449CA0','Blocks relative zoomDWORDD80; busyDWORDDD8 also blocks this method.'),(16,'DisableRelativeViewDistance','449FC0','Previously baselineUNKNOWN_10; blocks delta at activeDWORDD8A. Absolute449F70 ignores flags.'),(32,'DisableRelativeLens','44A070','Previously baselineUNKNOWN_20; blocks pointer delta at activeDWORDD8E. Absolute44A020 ignores flags.'),(64,'DisablePositionSetAndDelta','449AC0/449BD0','Blocks both direct and relative positionD68; busyDD8 also blocks.449B30 clamps each coordinate to signed[min,max-1].'),(128,'DisableModeChangeGate','44ACE0:44AF3F','Static assembly: active flags80 jumps to return0 before preset copy/application. Complete mode activation not emulated here; no claim of universal immutability.')]]
    s=dict(family='Things Cameras',tag=205,payload_bytes=84,envelope_bytes=8,fields=fields,flags=flags,executable_sha256=load('executable-hash-verification.json'),primary_program_bytes=primary(),native_data=native_data(),evidence=[whole(r['before']) for r in load('phase40-primary-manifest.json')],native_emulations=load('phase40-camera-emulations.json')['cases'],corpus=corpus(),
        parser=dict(game='0x570A20',editor='0x431220',game_callback_offset=164,editor_callback_offset=168,rule='Callback path: exact84 reads84; other declared lengths first zero84-byte raw buffer, then read declared length without upper bound. API allows only0..84, zero pads and keeps physical length. Non-callback path seeks declared length instead, no conversion/read callback.',intermediate_bytes=152,presence_dwords=17,offsets=dict(position=68,min_clip=80,max_clip=92,view=104,zoom=116,lens=128,flags=140,angles=144,id=150,opaque_tail=151),converter='Both56F900/42FE20 copy raw0..47, OR rawFlags48 into mid8C, copy raw4C..52 into mid90..96, leave mid97 unchanged. Parsers use zero initializer56F850/42FD70.'),
        game=dict(callback='0x5215F0',preset_store='0x449A30',chain='Get camera manager through world4 -> child10 -> virtualD0, checksum152, then store preset. Returns1 even for ignored IDs.',slot='Only unsigned BYTE id1..18 accepted. Destination cameraManager+28+id*98; copy all152 bytes. This stores configuration; it does not directly set current camera position.',setting='If unsigned globalDWORD759AEC<5: force intermediateDWORD20=1, replace ZoomMax mid7C with signed32(ZoomMin+trunc0(signed32(ZoomMax-ZoomMin)/3)). Other values copied. Phase46 identifies global759AEC as native Machine Spec Level, settings object759A78+74; see camera-machine-spec-semantics.json and41 native cases. Phase40 alone did not identify it.',active_mapping='Inspected activation44ACE0 branch copies presetFlags into activeD92, zoom bounds toD50/54, lens boundsD58/5C, view boundsD60/64. Subsequent choices depend on mode/world/timeline. Entire activation state machine is not simulated.'),
        controls=dict(position='449AC0 direct and449BD0 relative setters block on flags40 or busyDD8.449B30 clamps signedXYZ to[min,max-1]; additions wrap32 bits.449B00 is another position-related provider, not named ViewDistance from its initial discovery label.',zoom='449CA0 relative addsDWORD then signed clamps to[D50,D54-1]; mask8 or busyDD8 skips. Preset Zoom fields are raw30/34/38.',view='449FC0 relative addsDWORD, mask10 skips.449F70 absolute ignores flags/busy and signed clamps to[D60,D64-1]. Preset ViewDistance fields raw24/28/2C.',lens='44A070 relative receives pointerDWORD delta; mask20 skips.44A020 absolute receives pointerDWORD, ignores flags/busy. Both signed clamp[D58,D5C-1]. Preset Lens fields raw3C/40/44.',angles='449D40 relative accepts pointers yaw,roll,pitch, masks1/2/4. BusyDD8 skips all. Modes1/2/10/11 use modulo2048 for each enabled angle; other modes impose different roll/pitch bounds. Seven native cases use mode1; tables and other branches retained as assembly. Matrix rebuild44D6D0 captured only.'),
        editor=dict(normal_registration='48B5F0 initializes context114 with real42C730, then assigns callbacks. Native fragment48B703..48B84D leaves camera slotA8 and precedingA4 zero, sets RoomA0 correctly; three seeds verify zero initialization. No camera callback assignment found in full registration function.',reader='With A8==0,431220 seeks past CD payload by declared length. Standalone callback-enabled parser still implements152-byte conversion and was explicitly tested; normal registration does not use it.',writer='Full4947C0 contains record-tag assignmentsC2..CC and noCD serialization branch. Normal inspected read/write path does not preserve CD as an opaque node. This is a loss risk for an input containing synthetic/custom CD; actual GUI open/save with such file was not performed.',false_leads='4921B0 and4922B0 are trigger condition/action callbacks registered at contextB8/BC, not camera callbacks. Discovery snapshots retained but excluded from camera primary manifest.'),
        limitations=['84 final native cases:16 parser,6 converter,6 skip,15 full game callback/preset store,21 delta controls,4 scalar absolute controls,6 position controls,7 relative angle controls,3 editor registration fragments. Cases compare full152-byte intermediate, entire0xC00 preset state or0xF00 active state as appropriate.','No CD records in the110 inspected Things inputs. All camera behavior/patch checks use declared synthetic fixtures; no real world camera was rendered or measured. Baseline Q12 display units and field labels are kept with scope, not extended into universal units for lens/view.','Full game preset callback uses manager provider and checksum fixtures; actual449A30 executes. Stored presets and active-camera state are separate. Complete44ACE0 transition, timeline, world/possessed modes and rendering remain unverified.','Active-control functions execute unchanged;44D6D0 matrix rebuild is a call-count fixture. Mode1 relative angle results do not establish behavior of every mode. Upper bounds are exclusive in inspected signed clamps, including unusual empty/reversed bounds arithmetic.','Editor registration verification executes actual context zero initializer plus final assignment fragment; earlier string/file setup is bypassed. Full registration assembly inspected; no actual GUI roundtrip or universal claim about other editor builds.','Original rawBYTE53 remains authoritative even though both converters ignore it. Do not merge it into a16-bit ID or zero it on independent save. Preserve full flagsDWORD and shortened raw payload lengths.','All Ghidra emulation substitutions are local EmulatorHelper memory only. No game process, executable or source data edits. Native writer omission is assembly evidence; independent raw-preserving codec keeps custom CD records.'])
    from build_camera_catalogue import SCOPE_UPDATE
