    (ROOT/'camera-semantics.json').write_text(json.dumps(s,ensure_ascii=False,indent=2),encoding='utf8');print('Cameras:',len(s['native_emulations']),'native cases;',s['corpus']['camera_records'],'corpus records;',s['corpus']['thing_files'],'Things files')
